/// GoRouter configuration for the Weft mobile app (task 2.1).
///
/// ALL Phase 2 routes are registered here up front, each pointing at a screen
/// file inside its owning feature folder — later agents replace the screen
/// file's contents and do not edit this file. Paths live in `routes.dart`;
/// the redirect policy lives in `redirect.dart` (pure + unit-tested).
///
///   /splash                 SplashScreen            features/splash
///   /language               LanguageScreen          features/language
///   /onboarding             OnboardingScreen        features/onboarding
///   /login[?from=/path]     LoginScreen             features/auth
///   /register               RegisterScreen          features/auth
///   ── home shell (StatefulShellRoute.indexedStack; tabs keep state) ──
///   /map                    MapScreen               features/map          (F-MAP)
///   /my-reports             MyReportsScreen         features/my_reports   (F-MAP)
///   /notifications          NotificationsScreen     features/notifications
///   /profile                ProfileScreen           features/profile
///   ── full screen, over the shell ──
///   /report                 ReportPhotoScreen       features/report       (F-REPORT)
///   /report/category        ReportCategoryScreen    features/report       (F-REPORT)
///   /report/details         ReportDetailsScreen     features/report       (F-REPORT)
///   /report/success  extra: CreateIssueResponse     features/report       (F-REPORT)
///   /issues/:id             IssueDetailScreen       features/issues       (F-MAP)
library;

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../core/storage/app_preferences.dart';
import '../core/widgets/state_views.dart';
import '../data/models/issue.dart';
import '../features/auth/login_screen.dart';
import '../features/auth/register_screen.dart';
import '../features/auth/state/auth_controller.dart';
import '../features/home/home_shell.dart';
import '../features/issues/issue_detail_screen.dart';
import '../features/language/language_screen.dart';
import '../features/map/map_screen.dart';
import '../features/my_reports/my_reports_screen.dart';
import '../features/notifications/notifications_screen.dart';
import '../features/onboarding/onboarding_screen.dart';
import '../features/profile/profile_screen.dart';
import '../features/report/report_category_screen.dart';
import '../features/report/report_details_screen.dart';
import '../features/report/report_photo_screen.dart';
import '../features/report/report_success_screen.dart';
import '../features/splash/splash_screen.dart';
import 'redirect.dart';
import 'routes.dart';

/// The app's single router. Rebuilt never; re-evaluates its redirect whenever
/// auth status, language choice or onboarding state changes.
final routerProvider = Provider<GoRouter>((ref) {
  final refresh = ValueNotifier<int>(0);
  void bump() => refresh.value++;
  ref.listen(authControllerProvider.select((s) => s.status), (_, _) => bump());
  ref.listen(selectedLanguageProvider, (_, _) => bump());
  ref.listen(onboardingSeenProvider, (_, _) => bump());

  final router = GoRouter(
    navigatorKey: GlobalKey<NavigatorState>(debugLabel: 'root'),
    initialLocation: Routes.splash,
    refreshListenable: refresh,
    redirect: (context, state) => resolveRedirect(
      uri: state.uri,
      auth: ref.read(authControllerProvider).status,
      languageChosen: ref.read(selectedLanguageProvider) != null,
      onboardingSeen: ref.read(onboardingSeenProvider),
    ),
    routes: buildAppRoutes(),
    errorBuilder: (context, state) => const _NotFoundScreen(),
  );
  ref.onDispose(() {
    router.dispose();
    refresh.dispose();
  });
  return router;
});

/// Route table. A function, not a shared list: shell branches own navigator
/// GlobalKeys, which must not be shared between two router instances.
List<RouteBase> buildAppRoutes() => [
  GoRoute(
    path: Routes.splash,
    builder: (context, state) => const SplashScreen(),
  ),
  GoRoute(
    path: Routes.language,
    builder: (context, state) => const LanguageScreen(),
  ),
  GoRoute(
    path: Routes.onboarding,
    builder: (context, state) => const OnboardingScreen(),
  ),
  GoRoute(
    path: Routes.login,
    builder: (context, state) =>
        LoginScreen(from: state.uri.queryParameters[Routes.fromParam]),
  ),
  GoRoute(
    path: Routes.register,
    builder: (context, state) => const RegisterScreen(),
  ),

  // ── Home shell: 4 tabs, each a branch with its own navigator/state ──
  StatefulShellRoute.indexedStack(
    builder: (context, state, navigationShell) =>
        HomeShell(navigationShell: navigationShell),
    branches: [
      StatefulShellBranch(
        routes: [
          GoRoute(
            path: Routes.map,
            builder: (context, state) => const MapScreen(),
          ),
        ],
      ),
      StatefulShellBranch(
        routes: [
          GoRoute(
            path: Routes.myReports,
            builder: (context, state) => const MyReportsScreen(),
          ),
        ],
      ),
      StatefulShellBranch(
        routes: [
          GoRoute(
            path: Routes.notifications,
            builder: (context, state) => const NotificationsScreen(),
          ),
        ],
      ),
      StatefulShellBranch(
        routes: [
          GoRoute(
            path: Routes.profile,
            builder: (context, state) => const ProfileScreen(),
          ),
        ],
      ),
    ],
  ),

  // ── Report flow (F-REPORT) — full screen over the shell ──
  GoRoute(
    path: Routes.report,
    builder: (context, state) => const ReportPhotoScreen(),
    routes: [
      GoRoute(
        path: 'category',
        builder: (context, state) => const ReportCategoryScreen(),
      ),
      GoRoute(
        path: 'details',
        builder: (context, state) => const ReportDetailsScreen(),
      ),
      GoRoute(
        path: 'success',
        builder: (context, state) {
          final extra = state.extra;
          return ReportSuccessScreen(
            result: extra is CreateIssueResponse ? extra : null,
          );
        },
      ),
    ],
  ),

  // ── Issue detail (F-MAP) — reachable from map, My Reports, notifications ──
  GoRoute(
    path: Routes.issueDetailPattern,
    builder: (context, state) =>
        IssueDetailScreen(issueId: state.pathParameters['id']!),
  ),
];

class _NotFoundScreen extends StatelessWidget {
  const _NotFoundScreen();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(),
      body: EmptyView(
        icon: Icons.explore_off_outlined,
        title: 'Page not found',
        message: "That link doesn't lead anywhere in Weft.",
        action: FilledButton(
          onPressed: () => context.go(Routes.map),
          child: const Text('Go to map'),
        ),
      ),
    );
  }
}
